window.A2_DASHBOARD_UNITS = [{"unit":1,"theme":"achieve – complex","cards":[{"w":"achieve","p":"v.","d":"to succeed in doing something after trying hard","c":"實現","s":"To succeed in this field, you must achieve a balance between work and relaxation.","t":"要在這個領域取得成功，您必須實現工作和放鬆之間的平衡。"},{"w":"achievement","p":"n.","d":"something good you succeed in doing after hard work","c":"成就","s":"Winning the medal was a significant achievement for the athlete.","t":"對於運動員來說，獲得這枚獎牌是一個重要的成就。"},{"w":"high-achiever","p":"n.","d":"a person who does very well in school or work","c":"高成就者","s":"She's always been a high-achiever since her school days.","t":"從上學時起，她一直是一個高成就者。"},{"w":"acquire","p":"v.","d":"to get or gain something","c":"獲得","s":"It's important to acquire new skills in this rapidly changing world.","t":"在這個快速變化的世界裡，獲得新技能很重要。"},{"w":"acquisition","p":"n.","d":"the act of getting something; something a company buys","c":"收購","s":"The company's recent acquisition has expanded its market share.","t":"公司最近的收購擴大了其市場份額。"},{"w":"administer","p":"v.","d":"to manage or be in charge of something","c":"管理","s":"It's the principal's duty to administer the school's policies.","t":"校長有責任管理學校的政策。"},{"w":"administration","p":"n.","d":"the work of managing a company or organization","c":"管理","s":"The administration of the new drug must be done carefully.","t":"必須小心管理新藥物。"},{"w":"administrative","p":"adj.","d":"about managing a company or organization","c":"管理的","s":"He holds an administrative position in the company.","t":"他在公司擔任管理職位。"},{"w":"affect","p":"v.","d":"to cause a change in someone or something","c":"影響","s":"The drought will affect the crop yield this year.","t":"乾旱將影響今年的作物產量。"},{"w":"effect","p":"n.","d":"a change or result caused by something","c":"效果","s":"The new policy had an immediate effect on productivity.","t":"新政策立即產生了對生產率的效果。"},{"w":"be in effect","p":"phr","d":"to be in use or have power (rules, laws)","c":"生效","s":"The new rules will be in effect from next month.","t":"新規定將從下個月開始生效。"},{"w":"appropriate","p":"adj.","d":"right or suitable for a situation","c":"適當的","s":"Is it appropriate to wear jeans to the meeting?","t":"穿牛仔褲參加會議合適嗎？"},{"w":"aspect","p":"n.","d":"one part or side of something","c":"方面","s":"The aspect of culture we'll study today is its influence on behavior.","t":"我們今天要研究的文化方面是它對行為的影響。"},{"w":"assist","p":"v.","d":"to help someone","c":"協助","s":"Can you assist me with this task?","t":"你能協助我完成這項任務嗎？"},{"w":"assistance","p":"n.","d":"help or support","c":"幫助","s":"I need your assistance in moving these boxes.","t":"我需要你的説明來移動這些盒子。"},{"w":"category","p":"n.","d":"a group of things of the same kind","c":"類別","s":"The museum is organized by category of artifacts.","t":"博物館按文物類別進行組織。"},{"w":"categorize","p":"v.","d":"to put things into groups","c":"分類","s":"The library categorize books by genre.","t":"圖書館按類型分類書籍。"},{"w":"chapter","p":"n.","d":"one part of a book","c":"章節","s":"I'll finish reading this chapter before going to bed.","t":"我會在睡覺前讀完這一章節。"},{"w":"charter","p":"n.","d":"an official document that sets out rules or rights","c":"憲章","s":"The company's charter outlines its mission and values.","t":"公司的憲章概述了其使命和價值觀。"},{"w":"commission","p":"n.","d":"an official group chosen to do a special job","c":"委員會","s":"She was appointed to the city's planning commission.","t":"她被任命為市規劃委員會。"},{"w":"community","p":"n.","d":"the people living in one area","c":"社區","s":"The entire community came together to help after the disaster.","t":"災難發生後，整個社區都團結起來提供幫助。"},{"w":"complex","p":"n.","d":"a group of buildings in one place","c":"綜合體","s":"The apartment complex has a gym and a swimming pool.","t":"公寓綜合體設有健身房和游泳池。"}]},{"unit":2,"theme":"complex – design","cards":[{"w":"complex","p":"adj.","d":"having many parts; hard to understand","c":"複雜的","s":"The situation is more complex than it appears.","t":"情況比看起來更複雜。"},{"w":"complicated","p":"adj.","d":"difficult to understand or deal with","c":"複雜的","s":"The machinery is complicated and requires training to use.","t":"機械複雜，需要培訓才能使用。"},{"w":"complication","p":"n.","d":"a new problem that makes things harder","c":"併發症","s":"The surgery was successful, with no complication.","t":"手術成功，沒有併發症。"},{"w":"computer","p":"n.","d":"an electronic machine for working with information","c":"電腦","s":"The computer crashed and I lost all my work.","t":"電腦崩潰了，我失去了所有的工作。"},{"w":"computerized","p":"adj.","d":"done or controlled by a computer","c":"電腦化的","s":"The factory is now fully computerized.","t":"工廠現在完全電腦化了。"},{"w":"conclude","p":"v.","d":"to end something; to decide after thinking","c":"結束","s":"After a lengthy discussion, they conclude the meeting.","t":"經過長時間的討論，他們結束了會議。"},{"w":"in conclusion","p":"phr","d":"finally; to finish what I am saying","c":"最後","s":"in conclusion, I believe that we should adopt this new policy.","t":"最後，我認為我們應該採納這項新政策。"},{"w":"conduct","p":"v.","d":"to let heat or electricity pass through","c":"導電，導熱","s":"Certain materials conduct electricity better than others.","t":"某些材料比其他材料更好地導電。"},{"w":"conduct","p":"v.","d":"to lead or direct (an orchestra or activity)","c":"指揮，引導","s":"She will conduct the orchestra tonight.","t":"她今晚將指揮這個管弦樂隊。"},{"w":"conduct","p":"n.","d":"the way a person behaves","c":"品格","s":"He is a man of good conduct.","t":"他是一個品格高尚的人。"},{"w":"consequence","p":"n.","d":"a result of an action","c":"結果","s":"Actions have consequence.","t":"行動有後果。"},{"w":"construct","p":"v.","d":"to build something","c":"建造","s":"They plan to construct a bridge over the river.","t":"他們計畫在河上建造一座橋樑。"},{"w":"construction","p":"n.","d":"the act of building something","c":"建築","s":"The construction of the new mall will be completed next year.","t":"新購物中心的建設將于明年完成。"},{"w":"construction site","p":"n.","d":"a place where a building is being built","c":"建築工地","s":"Workers were busy at the construction site.","t":"工人們在建築工地忙碌地工作。"},{"w":"consume","p":"v.","d":"to use something such as energy or food","c":"消耗","s":"This device doesn't consume much energy.","t":"這個設備不消耗太多能源。"},{"w":"consumer","p":"n.","d":"a person who buys and uses goods","c":"消費者","s":"The product was popular among young consumer.","t":"該產品在年輕消費者中很受歡迎。"},{"w":"consumption","p":"n.","d":"the amount of something that is used","c":"消耗","s":"The country's oil consumption has increased.","t":"該國的石油消耗量已經增加。"},{"w":"credit","p":"n.","d":"trust that you will pay money back later","c":"信用","s":"Good credit is essential for getting a loan.","t":"良好的信用對於獲得貸款至關重要。"},{"w":"credit","p":"n.","d":"a unit of study at college or university","c":"學分","s":"She needs 3 more credit to graduate, so she's taking an extra course.","t":"她還需要3個學分才能畢業，所以她正在上一門額外的課程。"},{"w":"culture","p":"n.","d":"the customs and way of life of a group","c":"文化","s":"Studying culture helps us understand societies better.","t":"研究文化有助於我們更好地瞭解社會。"},{"w":"cultural","p":"adj.","d":"about culture","c":"文化的","s":"The city is known for its cultural festivals.","t":"該城市以其文化節日而著稱。"},{"w":"design","p":"n.","d":"the way something is planned or made","c":"設計","s":"He came up with an innovative design for the website.","t":"他為網站提出了一個創新的設計。"}]},{"unit":3,"theme":"design – institution","cards":[{"w":"design","p":"v.","d":"to plan and make something","c":"設計","s":"This renowned fashion designer wants to design her own line of clothing.","t":"這位名的室內設計師想設計自己的服裝系列。"},{"w":"distinct","p":"adj.","d":"clearly different","c":"明顯的","s":"There's a distinct difference between the two concepts.","t":"這兩個概念之間有明顯的區別。"},{"w":"distinction","p":"n.","d":"a clear difference between things","c":"區別","s":"The distinction between the two species is subtle.","t":"這兩個物種之間的區別是微妙的。"},{"w":"distinctive","p":"adj.","d":"special and easy to recognize","c":"有特色的","s":"Her voice is distinctive and easily recognizable.","t":"她的嗓音很有特色，容易識別。"},{"w":"element","p":"n.","d":"one basic part of something","c":"元素","s":"Water is composed of two element: hydrogen and oxygen.","t":"水由兩種元素組成：氫和氧。"},{"w":"equation","p":"n.","d":"a math statement with an equal sign","c":"方程","s":"The mathematical equation was difficult to solve.","t":"這個數學方程很難解。"},{"w":"equivalent","p":"adj.","d":"equal in value or meaning","c":"相等的","s":"Ten dollars is equivalent to a thousand rubles.","t":"十美元相當於一千盧布。"},{"w":"evaluate","p":"v.","d":"to judge how good or useful something is","c":"評估","s":"We need to evaluate the project's feasibility.","t":"我們需要評估專案的可行性。"},{"w":"evaluation","p":"n.","d":"a judgment of how good something is","c":"評價","s":"The teacher gave an evaluation of each student's performance.","t":"老師評價了每個學生的表現。"},{"w":"feature","p":"n.","d":"an important or typical part","c":"特點","s":"The main feature of this product is its durability and compatibility with various electronic devices.","t":"該產品的主要特點是其耐用性以及與各式各樣電子裝置的相容性。"},{"w":"feature","p":"v.","d":"to have something as an important part","c":"以...為特色","s":"The exhibition will feature artwork from local artists.","t":"展覽將以當地藝術家的藝術品為特色。"},{"w":"final","p":"adj.","d":"last","c":"最後的","s":"This is the final version of the report.","t":"這是報告的最終版本。"},{"w":"finalize","p":"v.","d":"to make the last decision about something","c":"定稿","s":"We need to finalize the plans by next week.","t":"我們需要在下周之前定稿計畫。"},{"w":"focus on = concentrate on","p":"phr","d":"to give all your attention to something","c":"聚焦於","s":"It's essential to focus on the task at hand.","t":"聚焦於手頭的任務是至關重要的。"},{"w":"remain/stay focused","p":"adj.","d":"to keep giving all your attention","c":"專注的","s":"He remained focused despite the distractions.","t":"儘管有分心的事，他仍然保持專注。"},{"w":"impact","p":"v.","d":"to have an effect on something","c":"影響","s":"The decision will impact the company's future.","t":"這一決定將影響公司的未來。"},{"w":"have a... impact on","p":"phr","d":"to have a strong effect on something","c":"對...有...的影響","s":"The policy will have a significant impact on the industry.","t":"該政策將對行業產生重大影響。"},{"w":"injury","p":"n.","d":"harm done to the body","c":"傷害","s":"He sustained an injury during the game.","t":"他在比賽中受傷。"},{"w":"injure","p":"v.","d":"to hurt someone","c":"受傷","s":"Be careful not to injure yourself while using these tools.","t":"使用這些工具時要小心不要受傷。"},{"w":"injured","p":"adj.","d":"hurt","c":"受傷的","s":"The injured player was taken off the field.","t":"受傷的球員被帶出了場地。"},{"w":"institute","p":"n.","d":"an organization for study or research","c":"機構","s":"The research institute published its findings last month.","t":"研究機構上個月發佈了其研究結果。"},{"w":"institution","p":"n.","d":"a large organization such as a school or bank","c":"機構","s":"He has been a member of that institution for a decade.","t":"他已經是那個機構的成員十年了。"}]},{"unit":4,"theme":"invest in – previous","cards":[{"w":"invest in","p":"phr","d":"to put money into something to make a profit","c":"投資於","s":"It's wise to invest in renewable energy now.","t":"現在投資于可再生能源是明智的。"},{"w":"investment in","p":"n.","d":"money put into something to make a profit","c":"投資","s":"The initial investment in infrastructure was high, but it paid off.","t":"最初在基礎項目的投資很高，但它得到了回報。"},{"w":"item","p":"n.","d":"one thing in a list or group","c":"項目","s":"Each item on the list must be checked.","t":"列表上的每一項都必須被檢查。"},{"w":"journal","p":"n.","d":"a magazine about a special subject","c":"期刊","s":"He published his findings in a scientific journal.","t":"他在一本科學期刊上發表了他的研究結果。"},{"w":"journal","p":"n.","d":"a magazine","c":"雜誌","s":"She reads that fashion journal every month.","t":"她每個月都讀那本時尚雜誌。"},{"w":"maintain","p":"v.","d":"to keep something in good condition","c":"維護","s":"It's important to maintain a balanced diet.","t":"保持均衡飲食很重要。"},{"w":"maintenance","p":"n.","d":"the work of keeping something in good condition","c":"維護","s":"The machine requires regular maintenance.","t":"機器需要定期維護。"},{"w":"normal","p":"adj.","d":"usual or ordinary","c":"正常的","s":"It's normal to feel nervous before an exam.","t":"考試前感到緊張是正常的。"},{"w":"abnormal","p":"adj.","d":"not normal; unusual","c":"不正常的","s":"His behavior was considered abnormal by many.","t":"他的行為被許多人認為是不正常的。"},{"w":"anomaly","p":"n.","d":"something that is different from what is normal","c":"異常","s":"The scientist noticed an anomaly in the data.","t":"科學家注意到資料中的一個異常。"},{"w":"obtain","p":"v.","d":"to get something","c":"獲得","s":"She managed to obtain rare manuscripts for her research.","t":"她設法為她的研究獲得了罕見的手稿。"},{"w":"obtained","p":"adj.","d":"gotten; received","c":"已獲得的","s":"The obtained results were promising.","t":"已獲得的結果很有希望。"},{"w":"participate in","p":"phr","d":"to take part in an activity","c":"參與","s":"She decided to participate in the marathon.","t":"她決定參加馬拉松。"},{"w":"participation","p":"n.","d":"taking part in an activity","c":"參與","s":"Active participation in class is crucial for understanding the material.","t":"積極參與課堂對理解材料至關重要。"},{"w":"perceive","p":"v.","d":"to notice or understand something","c":"感知","s":"Some animals can perceive ultrasonic sounds.","t":"一些動物可以感知超聲波。"},{"w":"perceived","p":"adj.","d":"seen or understood in a certain way","c":"感知到的","s":"His perceived threats turned out to be harmless.","t":"他感知到的威脅結果是無害的。"},{"w":"perception","p":"n.","d":"the way you see or understand something","c":"感知","s":"Beauty lies in the perception of the beholder.","t":"美在觀察者的感知中。"},{"w":"positive","p":"adj.","d":"good, hopeful or helpful","c":"積極正面的","s":"She always has a positive attitude towards life.","t":"她對生活總是持有積極的態度。"},{"w":"negative","p":"adj.","d":"bad or harmful; not hopeful","c":"消極負面的","s":"His negative feedback was taken into consideration.","t":"他的消極回饋被考慮在內。"},{"w":"potential","p":"adj.","d":"possible in the future","c":"潛在的","s":"There are potential risks involved.","t":"這其中涉及潛在的風險。"},{"w":"potential","p":"n.","d":"the ability to become good in the future","c":"潛力","s":"The young athlete showed great potential in the tryouts.","t":"年輕的運動員在試訓中表現出了很大的潛力。"},{"w":"previous","p":"adj.","d":"happening before","c":"之前的","s":"Please refer to the previous email for more details.","t":"請參考之前的電子郵件以獲取更多詳細資訊。"}]},{"unit":5,"theme":"previously – restriction","cards":[{"w":"previously","p":"adv.","d":"before now; earlier","c":"以前","s":"As I previously mentioned, the deadline is tomorrow.","t":"正如我之前提到的，截止日期是明天。"},{"w":"primary","p":"adj.","d":"main; most important","c":"主要的","s":"Our primary goal is to improve customer satisfaction.","t":"我們的主要目標是提高客戶滿意度。"},{"w":"make a purchase","p":"phr","d":"to buy something","c":"購買","s":"The make a purchase was made last week.","t":"購買是上周完成的。"},{"w":"purchase","p":"v.","d":"to buy something","c":"購買","s":"I decided to purchase a new car.","t":"我決定購買一輛新車。"},{"w":"range","p":"n.","d":"the amount between the lowest and highest","c":"範圍","s":"The price range varies depending on the product.","t":"價格範圍根據產品而異。"},{"w":"range from...to..","p":"phr","d":"to be between two numbers or amounts","c":"從...到...範圍","s":"The ages of the participants range from 18 to 35.","t":"參與者的年齡從18到35歲不等。"},{"w":"region","p":"n.","d":"a large area of a country or the world","c":"地區","s":"The region is known for its wine production.","t":"該地區以其葡萄酒生產而聞名。"},{"w":"regional","p":"adj.","d":"about a region","c":"地區的","s":"The regional dialect is difficult for outsiders to understand.","t":"地方方言對外來者來說很難理解。"},{"w":"regulate","p":"v.","d":"to control something with rules","c":"調節","s":"The government will regulate the industry more strictly.","t":"政府將更嚴格地調節該行業。"},{"w":"regulation","p":"n.","d":"an official rule","c":"規定","s":"There are certain regulation one must follow in the lab.","t":"實驗室中必須遵循某些規定。"},{"w":"relevant","p":"adj.","d":"connected to what is being discussed","c":"相關的","s":"Please only provide relevant information.","t":"請只提供相關資訊。"},{"w":"reside in = live in","p":"v.","d":"to live in a place","c":"居住","s":"My family resides in a small village.","t":"我的家人住在一個小村莊。"},{"w":"resident","p":"n.","d":"a person who lives in a place","c":"居民","s":"The local resident were upset about the construction noise.","t":"當地居民對建築噪音感到不滿。"},{"w":"residential","p":"adj.","d":"used for people to live in","c":"住宅的","s":"The new development will have both commercial and residential properties.","t":"新的開發專案將包括商業和住宅屬性。"},{"w":"residence","p":"n.","d":"the place where someone lives","c":"住所","s":"Their residence is near the beach.","t":"他們的住所靠近海灘。"},{"w":"source","p":"n.","d":"where something comes from","c":"來源","s":"The source of the leak has been identified.","t":"洩漏的來源已被確定。"},{"w":"resource","p":"n.","d":"something useful, like water, oil or money","c":"資源","s":"Water is a precious resource.","t":"水是寶貴的資源。"},{"w":"human and natural resources","p":"phr","d":"people and things from nature a country can use","c":"人力和自然資源","s":"The country's growth is driven by its abundant human and natural resources.","t":"該國的增長受到其豐富的人力和自然資源的驅動。"},{"w":"resourceful","p":"adj.","d":"good at finding ways to solve problems","c":"足智多謀的","s":"He's a resourceful individual who can find a solution to almost any problem.","t":"他是一個足智多謀的人，幾乎可以找到任何問題的解決方案。"},{"w":"restrict","p":"v.","d":"to limit something","c":"限制","s":"The law will restrict the sale of alcohol.","t":"法律將限制酒精的銷售。"},{"w":"restricted","p":"adj.","d":"limited; only for some people","c":"受限的","s":"Access to the area is restricted.","t":"該地區的通行受到限制。"},{"w":"restriction","p":"n.","d":"a rule that limits something","c":"限制","s":"There are certain restriction on freedom of speech.","t":"言論自由有某些限制。"}]},{"unit":6,"theme":"secure – transfer","cards":[{"w":"secure","p":"adj.","d":"safe; protected","c":"安全的","s":"The facility is secure and monitored 24/7.","t":"該設施是安全的，並且24/7進行監控。"},{"w":"secure","p":"v.","d":"to get something important; to fasten firmly","c":"獲得；固定","s":"She managed to secure a place in the highly competitive program.","t":"她設法在競爭激烈的項目中獲得了一個位置。"},{"w":"security","p":"n.","d":"protection from danger or crime","c":"安全","s":"The new system provides better security against theft.","t":"新系統提供了更好的防盜安全性。"},{"w":"seek-sought-sought","p":"v.","d":"to look for or try to get something","c":"尋求","s":"She seek-sought-sought advice from her mentor.","t":"她尋求了導師的建議。"},{"w":"select","p":"v.","d":"to choose something","c":"選擇","s":"Please select your preferred option from the list.","t":"請從清單中選擇您的首選選項。"},{"w":"selection","p":"n.","d":"a group of things to choose from","c":"選擇","s":"There's a wide selection of desserts available.","t":"有各種各樣的甜點可供選擇。"},{"w":"selective","p":"adj.","d":"careful about what you choose","c":"有選擇性的","s":"Be selective about the information you share online.","t":"對您線上分享的資訊要有選擇性。"},{"w":"site","p":"n.","d":"a place where something is or happened","c":"地點","s":"The site of the ancient temple is now a tourist attraction.","t":"古廟的遺址現在是一個旅遊景點。"},{"w":"strategy","p":"n.","d":"a plan to reach a goal","c":"策略","s":"The company's marketing strategy proved to be very effective.","t":"該公司的行銷策略被證明非常有效。"},{"w":"survey","p":"v.","d":"to ask many people questions to learn their opinions","c":"調查","s":"We will survey the employees to get their feedback.","t":"我們將調查員工以獲取他們的回饋。"},{"w":"survey","p":"n.","d":"a set of questions to learn people's opinions","c":"調查","s":"According to the survey, most people prefer online shopping.","t":"根據調查，大多數人更喜歡線上購物。"},{"w":"text","p":"n.","d":"the written words in a book or document","c":"文本","s":"Please refer to the text for a detailed explanation.","t":"請參閱文本以獲取詳細解釋。"},{"w":"text","p":"v.","d":"to send a message by phone","c":"發短信","s":"I'll text you the address.","t":"我會發短信給你地址。"},{"w":"context","p":"n.","d":"the situation or words around something","c":"上下文","s":"Without context, the statement can be misleading.","t":"如果沒有上下文，聲明可能會產生誤導。"},{"w":"tradition","p":"n.","d":"a custom passed down from the past","c":"傳統","s":"It's a tradition in our family to have a big reunion every year.","t":"我們家的傳統是每年都有一個大團圓。"},{"w":"traditional","p":"adj.","d":"following old customs","c":"傳統的","s":"They wore traditional costumes for the festival.","t":"他們穿傳統服裝參加節日。"},{"w":"transfer","p":"v.","d":"to move from one place to another","c":"轉移","s":"You can transfer the funds to my account.","t":"您可以將資金轉移到我的帳戶。"},{"w":"transfer","p":"n.","d":"moving someone or something to another place","c":"轉移；調動","s":"He requested a job transfer from the company's headquarter to the regional branch in Shanghai.","t":"他要求將工作轉移從公司總部移到在上海的分支機搆。"}]}];
